// Validate Input: normalises the request and enforces the limits set in "Config".
// Nothing in this node needs editing.
const cfg = $input.first().json;                 // settings from the Config node
const hook = $('Chat Webhook').first().json;     // raw webhook request
const body = hook.body && typeof hook.body === 'object' && !Array.isArray(hook.body) ? hook.body : {};

const num = (v, d) => (v === '' || v === null || v === undefined || !Number.isFinite(Number(v)) ? d : Number(v));
const CONTROL_CHARS = /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g;
const squash = (v) => String(v ?? '').replace(CONTROL_CHARS, ' ').replace(/\s+/g, ' ').trim();
const reject = (error, message) => [{ json: { valid: false, statusCode: 400, response: { success: false, error, message } } }];

// 1) Question
const maxLen = Math.max(50, num(cfg.maxQuestionLength, 1000));
const rawQuestion = body.question ?? body.message ?? body.text ?? body.query ?? body.chatInput;
const question = typeof rawQuestion === 'string' ? squash(rawQuestion) : '';
if (!question) return reject('question_required', 'Please type a question.');
if (question.length > maxLen) return reject('question_too_long', `Your message is too long. Please keep it under ${maxLen} characters.`);

// 2) Session id (the website may send one to keep a conversation together)
const sid = typeof body.sessionId === 'string' ? body.sessionId.trim() : '';
const sessionId = /^[A-Za-z0-9_-]{1,64}$/.test(sid) ? sid : 's_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);

// 3) Optional chat history (stateless memory: the website sends the last few messages)
const maxHistory = Math.max(0, Math.floor(num(cfg.maxHistoryMessages, 6)));
const roleOf = (r) => {
  const x = String(r || '').toLowerCase();
  if (x === 'user' || x === 'customer') return 'user';
  if (x === 'assistant' || x === 'bot' || x === 'ai') return 'assistant';
  return '';
};
const cleaned = (Array.isArray(body.history) ? body.history : [])
  .map((m) => ({ role: roleOf(m && m.role), content: squash(m && (m.content ?? m.text ?? m.message)).slice(0, 500) }))
  .filter((m) => m.role && m.content);
const history = maxHistory > 0 ? cleaned.slice(-maxHistory) : [];

// 4) Short follow-ups ("and for annual plans?") are searched together with the previous question
const lastUser = [...history].reverse().find((m) => m.role === 'user');
const searchQuery = (question.split(' ').length < 5 && lastUser ? lastUser.content + ' ' + question : question).slice(0, maxLen);

// 5) Optional customer details (only used when a human has to follow up)
const email = squash(body.email).slice(0, 254);
const pageUrl = squash(body.pageUrl).slice(0, 300);
const customer = {
  name: squash(body.name).slice(0, 80),
  email: /^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]{2,}$/.test(email) ? email : '',
};

const esBase = String(cfg.esUrl || '').trim().replace(/\/+$/, '');

return [{
  json: {
    ...cfg,
    valid: true,
    question,
    searchQuery,
    sessionId,
    history,
    customer,
    pageUrl: /^https?:\/\//i.test(pageUrl) ? pageUrl : '',
    esSearchUrl: `${esBase}/${String(cfg.esIndex || 'support-kb').trim()}/_search`,
    esLogUrl: `${esBase}/${String(cfg.esLogIndex || 'support-chat-logs').trim()}/_doc`,
    startedAt: Date.now(),
  },
}];

